# frozen_string_literal: true

require_relative "test_helper"

# In-process parity against golden outputs authored by the reference Python
# implementation (regenerate with test/support/generate_goldens.rb). The
# configurations are a pairwise covering array over the generation pipeline's
# option surface — schema features x strength x seed x pool size x row limits
# x output format — generated by Lattice itself from
# test/fixtures/generation_surface.lattice.yaml.
#
# Unlike test/python_parity_test.rb (which diffs live subprocesses), these
# assertions run the Ruby pipeline in-process, so mutation testing can use
# them to kill mutants anywhere in the generation path.
class GoldenParityTest < Minitest::Test
  cover "Lattice::IPOG*"
  cover "Lattice::ConstraintEngine*"
  cover "Lattice::Formatters*"
  cover "Lattice::MersenneTwister*"
  cover "Lattice::Parser*"
  cover "Lattice::Parameter*"
  cover "Lattice::Model*"

  include FixtureHelpers

  GOLDEN_DIR = File.join(FixtureHelpers::FIXTURES, "golden")
  MANIFEST = JSON.parse(File.read(File.join(GOLDEN_DIR, "manifest.json")))

  SCHEMA_FILES = { "simple" => "simple.json", "constrained" => "constrained.json", "skillit" => "skillit.json" }.freeze
  SEEDS = { "default" => 42, "alt" => 7 }.freeze
  POOL_SIZES = { "minimal" => 1, "default" => 50 }.freeze
  MAX_ROWS_LIMIT = 3
  STOP_PCT_LIMIT = 75.0

  def run_pipeline(values)
    seed = SEEDS.fetch(values.fetch("seed"))
    model = Lattice::Parser.load_model(
      fixture_path(SCHEMA_FILES.fetch(values.fetch("schema"))),
      strength_override: Integer(values.fetch("strength"))
    )
    result = Lattice::IPOG.generate_covering_array(
      model,
      strength: model.strength,
      seed: seed,
      pool_size: POOL_SIZES.fetch(values.fetch("pool_size")),
      max_rows: values["row_limit"] == "max_rows" ? MAX_ROWS_LIMIT : nil,
      stop_after_coverage: values["row_limit"] == "stop_pct" ? STOP_PCT_LIMIT : nil
    )
    Lattice::Formatters.render_output(model, result, output_format: values.fetch("format"), seed: seed) + "\n"
  end

  MANIFEST.each do |entry|
    define_method("test_golden_parity_#{entry.fetch('slug')}") do
      golden = File.read(File.join(GOLDEN_DIR, "#{entry.fetch('slug')}.golden"))
      assert_equal golden, run_pipeline(entry.fetch("values")),
                   "Ruby output diverged from Python golden for #{entry.fetch('slug')}"
    end
  end
end
